{
  "book_code": "TADAM",
  "verses": [
    {
      "chapter": 44,
      "verse": 2,
      "text_ar": "بيت شيث. وقال آدم لحواء: 'ماذا فعلتِ؟ لقد جلبَتِ علينا بلاءً عظيماً، وتعدياً وخطيئةً لكل أجيالنا: وهذا الذي فعلتِه، أخبري به"
    },
    {
      "chapter": 44,
      "verse": 3,
      "text_ar": "أولادكِ بعد موتي، [لأن الذين يخرجون منّا سيتعبون ويفشلون ولكنهم سيزدادون"
    },
    {
      "chapter": 44,
      "verse": 4,
      "text_ar": "نقصاً ويلعنوننا و(يقولون)، إن كل الشرور قد جلبها أبوانا علينا، اللذان كانا في"
    },
    {
      "chapter": 44,
      "verse": 5,
      "text_ar": "البداية].' ولما سمعت حواء هذه الكلمات، شرعت تبكي وتنوح."
    },
    {
      "chapter": 45,
      "verse": 1,
      "text_ar": "وكما سبق رئيس الملائكة ميخائيل فأنذر"
    }
  ]
}
